    [SCB-824] disable PieChart unhighlight function in android and ios native code

diff --git a/android/src/main/java/com/github/wuxudong/rncharts/charts/CustomPieChart.java b/android/src/main/java/com/github/wuxudong/rncharts/charts/CustomPieChart.java
new file mode 100644
index 0000000..6110ef6
--- /dev/null
+++ b/android/src/main/java/com/github/wuxudong/rncharts/charts/CustomPieChart.java
@@ -0,0 +1,43 @@
+package com.github.wuxudong.rncharts.charts;
+
+import android.content.Context;
+import android.util.AttributeSet;
+import android.view.MotionEvent;
+import android.view.View;
+
+import com.github.mikephil.charting.charts.PieChart;
+import com.github.mikephil.charting.highlight.Highlight;
+import com.github.mikephil.charting.listener.ChartTouchListener;
+import com.github.mikephil.charting.listener.OnChartGestureListener;
+import com.github.mikephil.charting.listener.PieRadarChartTouchListener;
+
+/**
+ * Created by rmin on 28/02/2018.
+ * Override to disable unhighlight function
+ */
+public class CustomPieChart extends PieChart {
+    public CustomPieChart(Context context) {
+        super(context);
+    }
+
+    public CustomPieChart(Context context, AttributeSet attrs) {
+        super(context, attrs);
+    }
+
+    public CustomPieChart(Context context, AttributeSet attrs, int defStyle) {
+        super(context, attrs, defStyle);
+    }
+
+    @Override
+    protected void init() {
+        super.init();
+
+        mChartTouchListener = new PieRadarChartTouchListener(this){
+
+            if (h != null && !h.equalTo(mLastHighlighted)) {
+                mChart.highlightValue(h, true);
+                mLastHighlighted = h;
+            }
+        };
+    }
+}

